package lucee.runtime.ai;

import lucee.runtime.op.Caster;
import lucee.runtime.type.Struct;

/**
 * Normalized token usage of one AI response (LDEV-6527). All values are in tokens, {@link #UNKNOWN}
 * means the provider did not report the value.
 * <ul>
 * <li>input: all tokens sent to the model, including the cached ones</li>
 * <li>output: all tokens generated by the model, including reasoning tokens when the provider
 * counts them as output</li>
 * <li>cached: the part of input that was read from a provider cache</li>
 * <li>reasoning: the part of output used for reasoning/thinking, when reported separately</li>
 * </ul>
 */
public final class AIUsage {

	public static final long UNKNOWN = -1L;

	public final long input;
	public final long output;
	public final long total;
	public final long cached;
	public final long reasoning;

	public AIUsage(long input, long output, long total, long cached, long reasoning) {
		this.input = input;
		this.output = output;
		this.cached = cached;
		this.reasoning = reasoning;
		if (total < 0L && input >= 0L && output >= 0L) total = input + output;
		this.total = total;
	}

	/**
	 * a value of the usage object as long, UNKNOWN when not set or not a number
	 */
	static long get(Struct sct, String key) {
		if (sct == null) return UNKNOWN;
		Object o = sct.get(key, null);
		if (o == null) return UNKNOWN;
		double d = Caster.toDoubleValue(o, true, Double.NaN);
		if (Double.isNaN(d) || d < 0) return UNKNOWN;
		return (long) d;
	}

	private static long sum(long a, long... others) {
		long res = a;
		for (long o: others) {
			if (o < 0L) continue;
			res = res < 0L ? o : res + o;
		}
		return res;
	}

	/**
	 * a provider reporting only zeros did not really report usage, a real call always has input
	 */
	private static AIUsage reported(AIUsage u) {
		if (u.input <= 0L && u.output <= 0L && u.total <= 0L) return null;
		return u;
	}

	/**
	 * OpenAI compatible "usage" object, null when the response has no usage
	 */
	public static AIUsage fromOpenAI(Struct usage) {
		if (usage == null || usage.isEmpty()) return null;
		long input = get(usage, "prompt_tokens");
		if (input < 0L) input = get(usage, "input_tokens");
		long output = get(usage, "completion_tokens");
		if (output < 0L) output = get(usage, "output_tokens");
		long total = get(usage, "total_tokens");
		long cached = get(Caster.toStruct(usage.get("prompt_tokens_details", null), null), "cached_tokens");
		if (cached < 0L) cached = get(Caster.toStruct(usage.get("input_tokens_details", null), null), "cached_tokens");
		if (cached < 0L) cached = get(usage, "prompt_cache_hit_tokens"); // DeepSeek
		long reasoning = get(Caster.toStruct(usage.get("completion_tokens_details", null), null), "reasoning_tokens");
		if (reasoning < 0L) reasoning = get(Caster.toStruct(usage.get("output_tokens_details", null), null), "reasoning_tokens");
		return reported(new AIUsage(input, output, total, cached, reasoning));
	}

	/**
	 * Claude "usage" object (for a stream the merged usage of message_start and message_delta). Claude
	 * reports the cached tokens separately from input_tokens, they are added to input to match the
	 * other providers.
	 */
	public static AIUsage fromClaude(Struct usage) {
		if (usage == null || usage.isEmpty()) return null;
		long cacheRead = get(usage, "cache_read_input_tokens");
		long cacheWrite = get(usage, "cache_creation_input_tokens");
		long input = sum(get(usage, "input_tokens"), cacheRead, cacheWrite);
		long output = get(usage, "output_tokens");
		return reported(new AIUsage(input, output, UNKNOWN, cacheRead, UNKNOWN));
	}

	/**
	 * Gemini "usageMetadata" object. Thinking tokens are not part of candidatesTokenCount, they are
	 * added to output.
	 */
	public static AIUsage fromGemini(Struct meta) {
		if (meta == null || meta.isEmpty()) return null;
		long input = sum(get(meta, "promptTokenCount"), get(meta, "toolUsePromptTokenCount"));
		long thoughts = get(meta, "thoughtsTokenCount");
		long output = sum(get(meta, "candidatesTokenCount"), thoughts);
		return reported(new AIUsage(input, output, get(meta, "totalTokenCount"), get(meta, "cachedContentTokenCount"), thoughts));
	}

	/**
	 * usage of a response that only knows the total (third party engines)
	 */
	public static AIUsage fromTotal(long total) {
		if (total <= 0L) return null;
		return new AIUsage(UNKNOWN, UNKNOWN, total, UNKNOWN, UNKNOWN);
	}

	public Struct toStruct(Struct sct) {
		if (input >= 0L) sct.setEL("input", input);
		if (output >= 0L) sct.setEL("output", output);
		if (total >= 0L) sct.setEL("total", total);
		if (cached >= 0L) sct.setEL("cached", cached);
		if (reasoning >= 0L) sct.setEL("reasoning", reasoning);
		return sct;
	}
}
